package main

// Architectural experiment, not generated production code. One schema-driven
// decoder serves every record layout and both output representations. Layout
// adapters are generated-code stand-ins: they contain storage access only.
import (
	"fmt"
	"math"
	"strings"
)

type datum struct {
	kind uint8
	data any
}

const (
	nullKind uint8 = iota
	stringKind
	integerKind
	numberKind
	booleanKind
	arrayKind
	recordKind
	maybeKind
	variantKind
)

type recordView interface {
	layout() *recordLayout
	get(int) datum
}
type recordBuilder interface {
	recordView
	set(int, datum)
}
type recordLayout struct {
	fields   []fieldSchema
	newTyped func() recordBuilder
}
type fieldSchema struct {
	name string
	node *schema
}
type schema struct {
	kind     uint8
	elem     *schema
	record   *recordLayout
	variants map[string]*schema
}

var stringSchema = &schema{kind: stringKind}
var intSchema = &schema{kind: integerKind}
var numberSchema = &schema{kind: numberKind}
var boolSchema = &schema{kind: booleanKind}
var profileLayout, userLayout, itemLayout, payloadLayout, viewLayout, purchaseLayout *recordLayout
var payloadSchema *schema

func optional(s *schema) *schema     { return &schema{kind: maybeKind, elem: s} }
func array(s *schema) *schema        { return &schema{kind: arrayKind, elem: s} }
func record(l *recordLayout) *schema { return &schema{kind: recordKind, record: l} }

func init() {
	profileLayout = &recordLayout{fields: []fieldSchema{
		{"city", stringSchema}, {"note", optional(stringSchema)}, {"scores", array(numberSchema)},
	}, newTyped: func() recordBuilder { return &profileRecord{} }}
	userLayout = &recordLayout{fields: []fieldSchema{
		{"active", boolSchema}, {"id", intSchema}, {"name", stringSchema}, {"profile", optional(record(profileLayout))}, {"tags", array(stringSchema)},
	}, newTyped: func() recordBuilder { return &userRecord{} }}
	itemLayout = &recordLayout{fields: []fieldSchema{
		{"price", numberSchema}, {"quantity", intSchema}, {"sku", stringSchema},
	}, newTyped: func() recordBuilder { return &itemRecord{} }}
	// Event's custom instance reads its tag first, then path/duration or
	// orderId/items. This intentionally differs from alphabetical record order.
	viewLayout = &recordLayout{fields: []fieldSchema{
		{"tag", stringSchema}, {"path", stringSchema}, {"duration", optional(intSchema)},
	}, newTyped: func() recordBuilder { return &viewRecord{} }}
	purchaseLayout = &recordLayout{fields: []fieldSchema{
		{"tag", stringSchema}, {"orderId", intSchema}, {"items", array(record(itemLayout))},
	}, newTyped: func() recordBuilder { return &purchaseRecord{} }}
	event := &schema{kind: variantKind, variants: map[string]*schema{"view": record(viewLayout), "purchase": record(purchaseLayout)}}
	payloadLayout = &recordLayout{fields: []fieldSchema{
		{"events", array(event)}, {"next", optional(stringSchema)}, {"users", array(record(userLayout))}, {"version", intSchema},
	}, newTyped: func() recordBuilder { return &payloadRecord{} }}
	payloadSchema = record(payloadLayout)
}

type decodeError struct {
	contexts []string
	expected string
}

func (e *decodeError) Error() string {
	last := "  No value was found."
	if e.expected != "" {
		last = fmt.Sprintf("  Expected value of type '%s'.", e.expected)
	}
	return strings.Join(append(append([]string{"An error occurred while decoding a JSON value:"}, e.contexts...), last), "\n")
}
func mismatch(expected string) *decodeError { return &decodeError{expected: expected} }
func wrapError(e *decodeError, contexts ...string) *decodeError {
	e.contexts = append(contexts, e.contexts...)
	return e
}

// DecodeArchitecture accepts the ordinary encoding/json representation.
// Builders are private and never escape until their whole record succeeds.
// The result remains in its selected representation; no normalization is timed.
func DecodeArchitecture(input any, model string) (any, error) {
	if model != "interfaces" && model != "descriptors" {
		return nil, fmt.Errorf("unknown model %q", model)
	}
	d, e := decodeSchema(payloadSchema, input, model == "interfaces")
	if e != nil {
		return nil, e
	}
	return d.data, nil
}

func decodeSchema(s *schema, input any, typed bool) (datum, *decodeError) {
	switch s.kind {
	case maybeKind:
		if input == nil {
			return datum{}, nil
		}
		return decodeSchema(s.elem, input, typed)
	case stringKind:
		if _, ok := input.(string); !ok {
			return datum{}, mismatch("String")
		}
	case booleanKind:
		if _, ok := input.(bool); !ok {
			return datum{}, mismatch("Boolean")
		}
	case numberKind, integerKind:
		n, ok := input.(float64)
		if !ok {
			return datum{}, mismatch("Number")
		}
		if s.kind == integerKind && (n != math.Trunc(n) || n < -2147483648 || n > 2147483647) {
			return datum{}, mismatch("Integer")
		}
	case arrayKind:
		values, ok := input.([]any)
		if !ok {
			return datum{}, mismatch("Array")
		}
		output := make([]datum, len(values))
		for i, value := range values {
			d, e := decodeSchema(s.elem, value, typed)
			if e != nil {
				return datum{}, wrapError(e, "  Under 'Array':", fmt.Sprintf("  At array index %d:", i))
			}
			output[i] = d
		}
		return datum{kind: arrayKind, data: output}, nil
	case recordKind, variantKind:
		obj, ok := input.(map[string]any)
		if !ok {
			return datum{}, mismatch("Object")
		}
		l := s.record
		if s.kind == variantKind {
			tag, ok := obj["tag"]
			if !ok {
				return datum{}, wrapError(mismatch(""), "  At object key 'tag':")
			}
			d, e := decodeSchema(stringSchema, tag, typed)
			if e != nil {
				return datum{}, wrapError(e, "  At object key 'tag':")
			}
			variant, ok := s.variants[d.data.(string)]
			if !ok {
				return datum{}, mismatch("Event tag")
			}
			l = variant.record
		}
		var result recordBuilder
		if typed {
			result = l.newTyped()
		} else {
			result = &descriptorRecord{shape: l, slots: make([]datum, len(l.fields))}
		}
		for i, f := range l.fields {
			value, present := obj[f.name]
			if !present && f.node.kind != maybeKind {
				return datum{}, wrapError(mismatch(""), fmt.Sprintf("  At object key '%s':", f.name))
			}
			d, e := decodeSchema(f.node, value, typed)
			if e != nil {
				return datum{}, wrapError(e, fmt.Sprintf("  At object key '%s':", f.name))
			}
			result.set(i, d)
		}
		return datum{kind: recordKind, data: recordView(result)}, nil
	default:
		panic("invalid schema")
	}
	return datum{kind: s.kind, data: input}, nil
}

func NormalizeArchitecture(decoded any, err error) any {
	if err != nil {
		return map[string]any{"error": err.Error()}
	}
	return map[string]any{"value": normalizeDatum(datum{kind: recordKind, data: decoded})}
}
func normalizeDatum(d datum) any {
	switch d.kind {
	case nullKind:
		return nil
	case arrayKind:
		src := d.data.([]datum)
		dst := make([]any, len(src))
		for i, v := range src {
			dst[i] = normalizeDatum(v)
		}
		return dst
	case recordKind:
		r := d.data.(recordView)
		dst := make(map[string]any, len(r.layout().fields))
		for i, f := range r.layout().fields {
			dst[f.name] = normalizeDatum(r.get(i))
		}
		return dst
	default:
		return d.data
	}
}

// Representation 1: one descriptor and a contiguous slot array per record.
type descriptorRecord struct {
	shape *recordLayout
	slots []datum
}

func (r *descriptorRecord) layout() *recordLayout { return r.shape }
func (r *descriptorRecord) get(i int) datum       { return r.slots[i] }
func (r *descriptorRecord) set(i int, d datum)    { r.slots[i] = d }

// Representation 2: private typed structs satisfying the embedded interfaces.
// These adapters perform no JSON reading, validation, traversal or decoding.
type optionalString struct {
	value string
	valid bool
}

func maybeString(d datum) optionalString {
	if d.kind == nullKind {
		return optionalString{}
	}
	return optionalString{d.data.(string), true}
}
func (s optionalString) datum() datum {
	if !s.valid {
		return datum{}
	}
	return datum{stringKind, s.value}
}

type optionalInt struct {
	value int32
	valid bool
}

func maybeInt(d datum) optionalInt {
	if d.kind == nullKind {
		return optionalInt{}
	}
	return optionalInt{int32(d.data.(float64)), true}
}
func (n optionalInt) datum() datum {
	if !n.valid {
		return datum{}
	}
	return datum{integerKind, float64(n.value)}
}

type profileRecord struct {
	city   string
	note   optionalString
	scores []datum
}

func (r *profileRecord) layout() *recordLayout { return profileLayout }
func (r *profileRecord) set(i int, d datum) {
	switch i {
	case 0:
		r.city = d.data.(string)
	case 1:
		r.note = maybeString(d)
	case 2:
		r.scores = d.data.([]datum)
	}
}
func (r *profileRecord) get(i int) datum {
	switch i {
	case 0:
		return datum{stringKind, r.city}
	case 1:
		return r.note.datum()
	case 2:
		return datum{arrayKind, r.scores}
	}
	panic("field")
}

type userRecord struct {
	active  bool
	id      int32
	name    string
	profile recordView
	tags    []datum
}

func (r *userRecord) layout() *recordLayout { return userLayout }
func (r *userRecord) set(i int, d datum) {
	switch i {
	case 0:
		r.active = d.data.(bool)
	case 1:
		r.id = int32(d.data.(float64))
	case 2:
		r.name = d.data.(string)
	case 3:
		if d.kind != nullKind {
			r.profile = d.data.(recordView)
		}
	case 4:
		r.tags = d.data.([]datum)
	}
}
func (r *userRecord) get(i int) datum {
	switch i {
	case 0:
		return datum{booleanKind, r.active}
	case 1:
		return datum{integerKind, float64(r.id)}
	case 2:
		return datum{stringKind, r.name}
	case 3:
		if r.profile == nil {
			return datum{}
		}
		return datum{recordKind, r.profile}
	case 4:
		return datum{arrayKind, r.tags}
	}
	panic("field")
}

type itemRecord struct {
	price    float64
	quantity int32
	sku      string
}

func (r *itemRecord) layout() *recordLayout { return itemLayout }
func (r *itemRecord) set(i int, d datum) {
	switch i {
	case 0:
		r.price = d.data.(float64)
	case 1:
		r.quantity = int32(d.data.(float64))
	case 2:
		r.sku = d.data.(string)
	}
}
func (r *itemRecord) get(i int) datum {
	switch i {
	case 0:
		return datum{numberKind, r.price}
	case 1:
		return datum{integerKind, float64(r.quantity)}
	case 2:
		return datum{stringKind, r.sku}
	}
	panic("field")
}

type payloadRecord struct {
	events  []datum
	next    optionalString
	users   []datum
	version int32
}

func (r *payloadRecord) layout() *recordLayout { return payloadLayout }
func (r *payloadRecord) set(i int, d datum) {
	switch i {
	case 0:
		r.events = d.data.([]datum)
	case 1:
		r.next = maybeString(d)
	case 2:
		r.users = d.data.([]datum)
	case 3:
		r.version = int32(d.data.(float64))
	}
}
func (r *payloadRecord) get(i int) datum {
	switch i {
	case 0:
		return datum{arrayKind, r.events}
	case 1:
		return r.next.datum()
	case 2:
		return datum{arrayKind, r.users}
	case 3:
		return datum{integerKind, float64(r.version)}
	}
	panic("field")
}

type viewRecord struct {
	tag, path string
	duration  optionalInt
}

func (r *viewRecord) layout() *recordLayout { return viewLayout }
func (r *viewRecord) set(i int, d datum) {
	switch i {
	case 0:
		r.tag = d.data.(string)
	case 1:
		r.path = d.data.(string)
	case 2:
		r.duration = maybeInt(d)
	}
}
func (r *viewRecord) get(i int) datum {
	switch i {
	case 0:
		return datum{stringKind, r.tag}
	case 1:
		return datum{stringKind, r.path}
	case 2:
		return r.duration.datum()
	}
	panic("field")
}

type purchaseRecord struct {
	tag     string
	orderID int32
	items   []datum
}

func (r *purchaseRecord) layout() *recordLayout { return purchaseLayout }
func (r *purchaseRecord) set(i int, d datum) {
	switch i {
	case 0:
		r.tag = d.data.(string)
	case 1:
		r.orderID = int32(d.data.(float64))
	case 2:
		r.items = d.data.([]datum)
	}
}
