package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"testing"
)

func TestArchitectureFixedOracle(t *testing.T) {
	const fixtures = "/Users/0x1/Documents/htdocs/altbak.pub-gopurs/test/fixtures/json-decoding/"
	var cases []struct {
		Name, Contents string
		Benchmark      bool
	}
	var expected struct{ Names, Fingerprints []string }
	load := func(path string, target any) {
		t.Helper()
		b, e := os.ReadFile(path)
		if e != nil {
			t.Fatal(e)
		}
		if e = json.Unmarshal(b, target); e != nil {
			t.Fatal(e)
		}
	}
	load(fixtures+"corpus.json", &cases)
	load(fixtures+"expected.json", &expected)
	if len(cases) != 17 || len(expected.Fingerprints) != len(cases) {
		t.Fatal("incomplete corpus")
	}
	for _, model := range []string{"interfaces", "descriptors"} {
		for i, c := range cases {
			t.Run(model+"/"+c.Name, func(t *testing.T) {
				if c.Name != expected.Names[i] {
					t.Fatal("case order")
				}
				var input any
				if e := json.Unmarshal([]byte(c.Contents), &input); e != nil {
					t.Fatal(e)
				}
				decoded, e := DecodeArchitecture(input, model)
				b, e := json.Marshal(NormalizeArchitecture(decoded, e))
				if e != nil {
					t.Fatal(e)
				}
				h := sha256.Sum256(b)
				actual := hex.EncodeToString(h[:])
				if actual != expected.Fingerprints[i] {
					t.Fatalf("fingerprint %s != %s; result %s", actual, expected.Fingerprints[i], b)
				}
			})
		}
	}
}

func TestArchitectureRecordStorageAndOwnership(t *testing.T) {
	for _, model := range []string{"interfaces", "descriptors"} {
		var input any
		if e := json.Unmarshal([]byte(`{"events":[],"users":[{"active":true,"id":42,"name":"a","tags":["x"]}],"version":1}`), &input); e != nil {
			t.Fatal(e)
		}
		first, e := DecodeArchitecture(input, model)
		if e != nil {
			t.Fatal(e)
		}
		second, e := DecodeArchitecture(input, model)
		if e != nil {
			t.Fatal(e)
		}
		if first == second {
			t.Fatal("record storage reused")
		}
		input.(map[string]any)["users"].([]any)[0].(map[string]any)["tags"].([]any)[0] = "changed"
		v := NormalizeArchitecture(first, nil).(map[string]any)["value"].(map[string]any)
		if v["users"].([]any)[0].(map[string]any)["tags"].([]any)[0] != "x" {
			t.Fatal("input aliases output")
		}
		switch model {
		case "interfaces":
			if _, ok := first.(*payloadRecord); !ok {
				t.Fatal("wrong typed representation")
			}
		case "descriptors":
			if _, ok := first.(*descriptorRecord); !ok {
				t.Fatal("wrong descriptor representation")
			}
		}
	}
}

