package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"runtime"
	"time"
)

var architectureSink any

func canonicalFingerprint(value any) string {
	data, err := json.Marshal(value)
	if err != nil {
		panic(err)
	}
	hash := sha256.Sum256(data)
	return hex.EncodeToString(hash[:])
}

func parseArchitecture(text string) any {
	var result any
	if err := json.Unmarshal([]byte(text), &result); err != nil {
		panic(err)
	}
	return result
}

func main() {
	model := os.Getenv("MODEL")
	if model != "interfaces" && model != "descriptors" {
		panic("set MODEL to interfaces or descriptors")
	}
	raw, err := os.ReadFile(os.Getenv("DIAG_CORPUS"))
	if err != nil {
		panic(err)
	}
	var files []struct {
		Name      string
		Contents  string
		Benchmark bool
	}
	if err = json.Unmarshal(raw, &files); err != nil {
		panic(err)
	}
	parsed := make([]any, len(files))
	names := make([]string, len(files))
	jsonHashes := make([]string, len(files))
	decodedHashes := make([]string, len(files))
	indices := []int{}
	for i, file := range files {
		names[i] = file.Name
		parsed[i] = parseArchitecture(file.Contents)
		jsonHashes[i] = canonicalFingerprint(parsed[i])
		decoded, decodeErr := DecodeArchitecture(parsed[i], model)
		decodedHashes[i] = canonicalFingerprint(NormalizeArchitecture(decoded, decodeErr))
		if file.Benchmark {
			indices = append(indices, i)
		}
	}
	if len(indices) == 0 {
		panic("empty timed corpus")
	}
	if os.Getenv("CHECK_ONLY") == "1" {
		data, err := json.Marshal(map[string]any{"names": names, "fingerprints": decodedHashes, "json_fingerprints": jsonHashes})
		if err != nil {
			panic(err)
		}
		fmt.Println(string(data))
		return
	}
	phases := map[string]any{}
	for _, phase := range []string{"parse", "decode", "combined"} {
		samples := []map[string]float64{}
		best := 1e100
		for pass := 0; pass < 7; pass++ {
			results := make([]any, len(indices))
			errors := make([]error, len(indices))
			var before, after runtime.MemStats
			runtime.ReadMemStats(&before)
			start := time.Now()
			for slot, i := range indices {
				switch phase {
				case "parse":
					results[slot] = parseArchitecture(files[i].Contents)
				case "decode":
					results[slot], errors[slot] = DecodeArchitecture(parsed[i], model)
				case "combined":
					results[slot], errors[slot] = DecodeArchitecture(parseArchitecture(files[i].Contents), model)
				}
				architectureSink = results[slot]
			}
			elapsed := float64(time.Since(start).Nanoseconds()) / 1000
			runtime.ReadMemStats(&after)
			for slot, result := range results {
				i := indices[slot]
				value, expected := result, jsonHashes[i]
				if phase != "parse" {
					value = NormalizeArchitecture(result, errors[slot])
					expected = decodedHashes[i]
				}
				if canonicalFingerprint(value) != expected {
					panic("unstable " + phase + ": " + files[i].Name)
				}
			}
			if pass >= 2 {
				if elapsed < best {
