	rt "recordprobe/runtime"
)

// The operation bodies below are deliberately shared by every layout. noinline
// prevents the benchmark caller specializing a single known concrete receiver.
// Each call reads an Int, String and Boolean and returns the same Int result.
type hasID interface{ ID() int64 }
type hasName interface{ Name() string }
type hasActive interface{ Active() bool }
type readable interface {
	hasID
	hasName
	hasActive
	fields() map[string]any // Only used by semantic tests, outside timing.
}

type scored interface {
	readable
	Score() int64
}

type extension struct {
	readable
	score int64
}

func (e *extension) Score() int64 { return e.score }
func (e *extension) fields() map[string]any {
	m := e.readable.fields()
	m["score"] = e.score
	return m
}

//go:noinline
func scoreInterface(r readable) int64 {
	v := r.ID()*3 + int64(len(r.Name()))
	if r.Active() {
		v += 7
	}
	return v
}

//go:noinline
func insertInterface(r readable) scored {
	return &extension{readable: r, score: scoreInterface(r)}
}

//go:noinline
func scoreValue(r rt.Value) int64 {
	v := rt.RecordGet(r, "id").IntVal*3 + int64(len(rt.RecordGet(r, "name").StrVal()))
	if rt.RecordGet(r, "active").IntVal != 0 {
		v += 7
	}
	return v
}

type coerced struct {
	Rc                                       uint32
	Active, ID, Name, Extra0, Extra1, Extra2 rt.Value
}

//go:noinline
func scoreCoerce(r rt.Value) int64 {
	s := rt.CoerceToStruct[coerced](r)
	v := s.ID.IntVal*3 + int64(len(s.Name.StrVal()))
	if s.Active.IntVal != 0 {
		v += 7
	}
	return v
}

//go:noinline
func insertValue(r rt.Value) rt.Value {
	return rt.RecordSet(r, "score", rt.Int(scoreValue(r)))
}

type layout struct {
	keys             []string
	id, name, active int
	extended         *layout
}

type slots struct {
	layout *layout
	values []rt.Value
}

//go:noinline
func scoreSlots(r *slots) int64 {
	v := r.values[r.layout.id].IntVal*3 + int64(len(r.values[r.layout.name].StrVal()))
	if r.values[r.layout.active].IntVal != 0 {
		v += 7
	}
	return v
}

//go:noinline
func insertSlots(r *slots) *slots {
	vs := make([]rt.Value, len(r.values)+1)
	copy(vs, r.values)
	vs[len(r.values)] = rt.Int(scoreSlots(r))
	return &slots{r.layout.extended, vs}
}

type input struct {
	id     int64
	name   string
	active bool
	extra0 int64
	extra1 float64
	extra2 string
}

func inputs() []input {
	x := make([]input, 256)
	for i := range x {
		x[i] = input{int64(i*97 - 311), fmt.Sprintf("name-%d-λ", i), i%3 != 0, int64(i) * 1009, float64(i) / 8, fmt.Sprintf("extra-%d", i)}
	}
	return x
}

var layouts = makeLayouts()

func makeLayouts() []*layout {
	x := make([]*layout, 32)
	for i := range x {
		base := []string{"id", "name", "active", fmt.Sprintf("x0_%d", i), fmt.Sprintf("x1_%d", i), fmt.Sprintf("x2_%d", i)}
		keys := append(append([]string{}, base[i%6:]...), base[:i%6]...)
		l := &layout{keys: keys}
		for j, k := range keys {
			switch k {
			case "id":
				l.id = j
			case "name":
				l.name = j
			case "active":
				l.active = j
			}
		}
		l.extended = &layout{keys: append(append([]string{}, keys...), "score"), id: l.id, name: l.name, active: l.active}
		x[i] = l
	}
	return x
}

func values(kind int, v input) []rt.Value {
	x := make([]rt.Value, 6)
	base := [6]rt.Value{rt.Int(v.id), rt.Str(v.name), rt.Bool(v.active), rt.Int(v.extra0), rt.Float(v.extra1), rt.Str(v.extra2)}
	for i := range x {
		x[i] = base[(i+kind%6)%6]
	}
	return x
}

//go:noinline
func makeValue(kind int, v input) rt.Value {
	return rt.RecordDict(layouts[kind].keys, values(kind, v))
}

//go:noinline
func makeSlots(kind int, v input) *slots {
	return &slots{layouts[kind], values(kind, v)}
}

func unbox(v rt.Value) any {
	switch v.Type {
	case rt.TypeInt:
		return v.IntVal
	case rt.TypeString:
		return v.StrVal()
	case rt.TypeBool:
		return v.IntVal != 0
	case rt.TypeFloat:
		return v.FloatVal()
	default:
		panic(fmt.Sprintf("unhandled %v", v.Type))
	}
}

func fieldsValue(v rt.Value) map[string]any {
	m := rt.RecordToMap(v)
	x := make(map[string]any, len(m))
	for k, v := range m {
		x[k] = unbox(v)
	}
	return x
}

func fieldsSlots(v *slots) map[string]any {
	x := make(map[string]any, len(v.values))
	for i, k := range v.layout.keys {
		x[k] = unbox(v.values[i])
	}
	return x
}

func orderedFields(m map[string]any) string {
	ks := make([]string, 0, len(m))
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	s := ""
	for _, k := range ks {
		s += fmt.Sprintf("%q:%T:%v;", k, m[k], m[k])
	}
	return s
}

