package recordprobe

import (
	"fmt"
	"runtime"
	"testing"

	rt "recordprobe/runtime"
)

var checksum int64
var valueSink rt.Value
var interfaceSink readable
var slotSink *slots

func TestSemanticEquivalence(t *testing.T) {
	for kind := range layouts {
		for _, in := range inputs() {
			value, iface, slots := makeValue(kind, in), makeInterface(kind, in), makeSlots(kind, in)
			want := in.id*3 + int64(len(in.name))
			if in.active {
				want += 7
			}
			for model, got := range map[string]int64{"value": scoreValue(value), "coerce": scoreCoerce(value), "interface": scoreInterface(iface), "slots": scoreSlots(slots)} {
				if got != want {
					t.Fatalf("%s layout %d: got %d want %d", model, kind, got, want)
				}
			}
			before := orderedFields(fieldsValue(value))
			if got := orderedFields(iface.fields()); got != before {
				t.Fatal("interface full record mismatch", kind, got, before)
			}
			if got := orderedFields(fieldsSlots(slots)); got != before {
				t.Fatal("slots full record mismatch", kind, got, before)
			}
			nv, ni, ns := insertValue(value), insertInterface(iface), insertSlots(slots)
			if rt.RecordGet(nv, "score").IntVal != want || ni.Score() != want || ns.values[6].IntVal != want {
				t.Fatal("inserted score mismatch")
			}
			after := orderedFields(fieldsValue(nv))
			if orderedFields(ni.fields()) != after || orderedFields(fieldsSlots(ns)) != after {
				t.Fatal("extension lost or changed original fields", kind)
			}
			if orderedFields(fieldsValue(value)) != before || orderedFields(iface.fields()) != before || orderedFields(fieldsSlots(slots)) != before {
				t.Fatal("insertion mutated source", kind)
			}
			if scoreValue(nv) != want || scoreInterface(ni) != want || scoreSlots(ns) != want {
				t.Fatal("extension broke original accessors")
			}
		}
	}
}

func TestInsertedInterfaceKeepsSourceAlive(t *testing.T) {
	x := make([]scored, 32)
	for i := range x {
		x[i] = insertInterface(makeInterface(i, inputs()[i]))
	}
	runtime.GC()
	for _, x := range x {
		if scoreInterface(x) != x.Score() {
			t.Fatal("GC changed source")
		}
	}
}

func BenchmarkAccess(b *testing.B) {
	ins := inputs()
	for _, n := range []int{1, 8, 32} {
		vs, is, ss := make([]rt.Value, len(ins)), make([]readable, len(ins)), make([]*slots, len(ins))
		for i, in := range ins {
			vs[i], is[i], ss[i] = makeValue(i%n, in), makeInterface(i%n, in), makeSlots(i%n, in)
		}
		b.Run(fmt.Sprintf("Value/layouts=%d", n), func(b *testing.B) {
			b.ReportAllocs()
			var sum int64
			for i := 0; i < b.N; i++ {
				sum += scoreValue(vs[i&255])
			}
			checksum = sum
		})
		b.Run(fmt.Sprintf("Coerce/layouts=%d", n), func(b *testing.B) {
			b.ReportAllocs()
			var sum int64
			for i := 0; i < b.N; i++ {
				sum += scoreCoerce(vs[i&255])
			}
			checksum = sum
		})
		b.Run(fmt.Sprintf("Interface/layouts=%d", n), func(b *testing.B) {
			b.ReportAllocs()
			var sum int64
			for i := 0; i < b.N; i++ {
				sum += scoreInterface(is[i&255])
			}
			checksum = sum
		})
		b.Run(fmt.Sprintf("Slots/layouts=%d", n), func(b *testing.B) {
			b.ReportAllocs()
			var sum int64
			for i := 0; i < b.N; i++ {
				sum += scoreSlots(ss[i&255])
			}
			checksum = sum
		})
	}
}

func BenchmarkConstructAndAccess(b *testing.B) {
	ins := inputs()
	for _, n := range []int{1, 8, 32} {
		b.Run(fmt.Sprintf("Value/layouts=%d", n), func(b *testing.B) {
			b.ReportAllocs()
			var sum int64
			for i := 0; i < b.N; i++ {
				valueSink = makeValue(i%n, ins[i&255])
				sum += scoreValue(valueSink)
			}
			checksum = sum
		})
		b.Run(fmt.Sprintf("Interface/layouts=%d", n), func(b *testing.B) {
			b.ReportAllocs()
			var sum int64
			for i := 0; i < b.N; i++ {
				interfaceSink = makeInterface(i%n, ins[i&255])
				sum += scoreInterface(interfaceSink)
			}
			checksum = sum
		})
		b.Run(fmt.Sprintf("Slots/layouts=%d", n), func(b *testing.B) {
			b.ReportAllocs()
			var sum int64
			for i := 0; i < b.N; i++ {
				slotSink = makeSlots(i%n, ins[i&255])
				sum += scoreSlots(slotSink)
			}
			checksum = sum
		})
	}
}

func BenchmarkImmutableInsertAndAccess(b *testing.B) {
	ins := inputs()
	for _, n := range []int{1, 8, 32} {
		vs, is, ss := make([]rt.Value, len(ins)), make([]readable, len(ins)), make([]*slots, len(ins))
		for i, in := range ins {
			vs[i], is[i], ss[i] = makeValue(i%n, in), makeInterface(i%n, in), makeSlots(i%n, in)
		}
		b.Run(fmt.Sprintf("Value/layouts=%d", n), func(b *testing.B) {
			b.ReportAllocs()
			var sum int64
			for i := 0; i < b.N; i++ {
				valueSink = insertValue(vs[i&255])
				sum += scoreValue(valueSink) + rt.RecordGet(valueSink, "score").IntVal
			}
			checksum = sum
		})
		b.Run(fmt.Sprintf("Interface/layouts=%d", n), func(b *testing.B) {
			b.ReportAllocs()
			var sum int64
			for i := 0; i < b.N; i++ {
				v := insertInterface(is[i&255])
				interfaceSink = v
				sum += scoreInterface(v) + v.Score()
			}
			checksum = sum
		})
		b.Run(fmt.Sprintf("Slots/layouts=%d", n), func(b *testing.B) {
			b.ReportAllocs()
			var sum int64
			for i := 0; i < b.N; i++ {
				slotSink = insertSlots(ss[i&255])
				sum += scoreSlots(slotSink) + slotSink.values[6].IntVal
			}
			checksum = sum
		})
	}
}

