#!/usr/bin/env python3
"""Bounded code-size check: 1/8/32 layouts, one body for polymorphic score.

Generates sources by default. Pass --build to build, inspect symbols and save
size-results.json. This checks adapter growth, not whole-compiler binary size.
"""
import argparse
import json
import os
from pathlib import Path
import subprocess

root = Path(__file__).resolve().parent
args = argparse.ArgumentParser()
args.add_argument('--build', action='store_true')
args = args.parse_args()
results = []
for n in (1, 8, 32):
    directory = root / 'size' / f'layouts-{n}'
    directory.mkdir(parents=True, exist_ok=True)
    fields = [('id', 'int64'), ('name', 'string'), ('active', 'bool'), ('extra0', 'int64'), ('extra1', 'float64'), ('extra2', 'string')]
    s = ['''package main
import ("fmt"; "os"; "strconv")
type hasID interface { ID() int64 }
type hasName interface { Name() string }
type hasActive interface { Active() bool }
type readable interface { hasID; hasName; hasActive }
type extension struct { readable; score int64 }
//go:noinline
func score(r readable) int64 {
 v := r.ID()*3 + int64(len(r.Name())); if r.Active() { v += 7 }; return v
}
//go:noinline
func insert(r readable) *extension { return &extension{r,score(r)} }
''']
    for i in range(n):
        order = fields[i % 6:] + fields[:i % 6]
        s += [f'type private{i} struct {{' + '; '.join(f'{name} {t}' for name, t in order) + '}\n']
        s += [f'func (r *private{i}) ID() int64 {{ return r.id }}\n', f'func (r *private{i}) Name() string {{ return r.name }}\n', f'func (r *private{i}) Active() bool {{ return r.active }}\n']
    s += ['//go:noinline\nfunc makeRecord(kind int, v int64) readable { switch kind {\n']
    for i in range(n):
        s += [f'case {i}: return &private{i}{{id:v,name:"abc",active:v%3==0,extra0:v*1009,extra1:float64(v)/8,extra2:"uvw"}}\n']
    s += ['default: panic("bad layout") } }\n']
    s += [f'''func main() {{
count := 1000; if len(os.Args)>1 {{ n,e:=strconv.Atoi(os.Args[1]); if e!=nil{{panic(e)}};count=n }}
rs:=make([]readable,{n}); for i:=range rs {{ rs[i]=makeRecord(i,int64(i)) }}
var sum int64; for i:=0;i<count;i++ {{ r:=rs[i%len(rs)]; e:=insert(r);sum+=score(r)+score(e)+e.score }}
fmt.Println(sum)
}}
''']
    source = directory / 'main.go'
    source.write_text(''.join(s))
    if args.build:
        env = {**os.environ, 'GOWORK': 'off'}
        subprocess.run(['go', 'build', '-trimpath', '-buildvcs=false', '-o', 'probe', '.'], cwd=directory, env=env, check=True)
        subprocess.run(['go', 'build', '-trimpath', '-buildvcs=false', '-ldflags=-s -w', '-o', 'probe-stripped', '.'], cwd=directory, env=env, check=True)
        nm_result = subprocess.run(['go', 'tool', 'nm', 'probe'], cwd=directory, env=env, text=True, capture_output=True)
        nm = nm_result.stdout if nm_result.returncode == 0 else subprocess.check_output(['nm', 'probe'], cwd=directory, env=env, text=True)
        symbols = [line.strip() for line in nm.splitlines() if line.split() and line.split()[-1].lstrip('_') == 'main.score']
        if len(symbols) != 1:
            raise RuntimeError(f'expected one polymorphic operation body: {symbols}')
        output = subprocess.check_output(['./probe', '1000'], cwd=directory, text=True).strip()
        expected = 3*sum(3*(i%n)+3+(7 if (i%n)%3==0 else 0) for i in range(1000))
        if int(output) != expected:
            raise RuntimeError((output, expected))
        results.append({'layouts':n, 'unstripped_bytes':(directory/'probe').stat().st_size, 'stripped_bytes':(directory/'probe-stripped').stat().st_size, 'score_body_symbols':symbols,'checksum':int(output)})
if args.build:
    (root/'size-results.json').write_text(json.dumps(results,indent=2)+'\n')
    print(json.dumps(results,indent=2))
else:
    print('Sources ready in size/layouts-{1,8,32}; run with --build after timing campaigns.')
